"""Build the static portfolio. Run: python build.py (standard library only)."""
import json
from pathlib import Path
from html import escape as e

ROOT = Path(__file__).resolve().parent
DIST = ROOT / 'dist'
C = json.loads((ROOT / 'content.json').read_text(encoding='utf-8'))
ORIGIN = 'https://saurav-sharma-data-portfolio.chandersaurav2016.chatgpt.site'
RESUME = '/resume/Saurav_Chander_Sharma_Resume.pdf'
PROJECTS = C['projects']

def ext(url, text, cls='text-link'):
    return f'<a class="{cls}" href="{e(url)}" target="_blank" rel="noopener noreferrer">{text}</a>'

def tags(items):
    return '<div class="tags">' + ''.join(f'<span class="tag">{e(x)}</span>' for x in items) + '</div>'

def resume(cls='btn secondary', text='Download Resume ↓'):
    return f'<a class="{cls}" href="{RESUME}" download>{text}</a>'

def header():
    links = ''.join(f'<a href="/{"#"+s}" data-section="{s}">{label}</a>' for s,label in [('home','Home'),('expertise','Expertise'),('projects','Projects'),('about','About'),('contact','Contact')])
    return f'''<a class="skip" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="brand" href="/" aria-label="Saurav home">Saurav<span>.</span></a><nav class="nav" id="navigation" aria-label="Main navigation">{links}{resume('mobile-resume','Download Resume ↓')}<a class="mobile-resume" href="mailto:{C['email']}">Email Me ↗</a></nav>{resume('btn resume')}<button class="theme-toggle" type="button" aria-label="Dark mode" aria-pressed="false" title="Switch to dark mode"><svg class="moon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14A8.5 8.5 0 0 1 10 3.5 8.5 8.5 0 1 0 20.5 14Z"/></svg><svg class="sun" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg></button><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="Toggle navigation">☰</button></div></header>'''

def footer():
    return f'''<footer class="footer"><div class="container"><div class="footer-top"><a class="brand" href="/">Saurav<span>.</span></a><div class="footer-links">{ext(C['github'],'GitHub ↗','')}{ext(C['linkedin'],'LinkedIn ↗','')}{resume('','Resume ↓')}<a href="#top">Back to top ↑</a></div></div><div class="footer-bottom"><span>© 2026 Saurav Chander Sharma</span><span>Data Analyst · Toronto, Ontario</span></div></div></footer>'''

def page(title, desc, body, path='/', schema=None):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="theme-color" content="#102347"><link rel="canonical" href="{ORIGIN}{path}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:image" content="{ORIGIN}/assets/social-preview.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><script src="/theme-init.js"></script><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script><script type="application/ld+json">{json.dumps(schema or {},ensure_ascii=False)}</script></head><body id="top">{header()}{body}{footer()}</body></html>'''

icons = [
 '<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',
 '<path d="M4 3v18h17M8 16v-5m5 5V6m5 10V9"/>',
 '<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-14-2 16"/>'
]
expertise = [
 ('Data Preparation & Modeling','Clean and transform raw data into reliable analytics layers with SQL, BigQuery, dbt, and Power Query.'),
 ('Dashboards & Business Intelligence','Bring performance metrics to life with Power BI, DAX, Tableau, and Excel.'),
 ('Python & Decision Analytics','Explore patterns and build practical decision-support tools with Python, Pandas, NumPy, and Streamlit.')
]
expert_cards = ''.join(f'<article class="expertise-card"><div class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">{icons[i]}</svg></div><div><h3>{title}</h3><p>{copy}</p></div></article>' for i,(title,copy) in enumerate(expertise))

def card(p, i):
    route = '/projects/'+p['slug']+'/'
    demo = ext(p['demo'],'Try Live Simulator ↗','text-link demo') if p.get('demo') else ''
    return f'''<article class="project-card"><a class="project-image" href="{route}" aria-label="View {e(p['title'])}"><img src="/assets/{p['slug']}-1.webp" alt="{e(p['images'][0])}" width="1332" height="752" loading="lazy"></a><div class="project-body"><div class="eyebrow">0{i+1} / {p['category']}</div><h3><a href="{route}">{p['shortTitle']}</a></h3><p>{p['summary']}</p>{tags(p['stack'])}<div class="project-metric"><strong>{p['metric']}</strong><span>{p['metricLabel']}</span></div><div class="project-links"><a class="text-link" href="{e(p['dashboardUrl'])}" target="_blank" rel="noopener noreferrer">View Dashboard <span class="arrow">↗</span></a>{ext(C['github']+'/'+p['repo'],'GitHub ↗','text-link github')}{demo}</div></div></article>'''

home = f'''<main id="main">
<section class="hero" id="home"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span>DATA ANALYST · TORONTO, CANADA</div><h1><span class="intro">Hi! I'm Saurav.</span>I turn complex data into <span class="accent">clear decisions.</span></h1><p>I build reliable data models, insightful dashboards, and practical analytics applications — connecting the numbers to the decisions that matter.</p><div class="actions"><a class="btn" href="#projects">Explore My Projects <span class="arrow">↗</span></a>{resume()}</div><div class="socials"><span class="line"></span>{ext(C['linkedin'],'LinkedIn ↗','text-link')}{ext(C['github'],'GitHub ↗','text-link')}</div></div><div class="portrait-scene"><div class="portrait-halo"></div><span class="orbit" aria-hidden="true"></span><span class="orbit two" aria-hidden="true"></span><span class="spark" aria-hidden="true">✳</span><div class="portrait-frame"><img src="/assets/portrait.jpg" alt="Saurav Chander Sharma" width="400" height="400" fetchpriority="high"></div><div class="metric-card metric-one"><div class="mini-label">FINTECH PROJECT</div><strong>416,747</strong><small>transactions analyzed</small><div class="tiny-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></div></div><div class="metric-card metric-two"><div class="mini-label">GA4 ECOMMERCE</div><strong>~72% <span class="accent">↘</span></strong><small>product-view to<br>add-to-cart drop-off</small></div><div class="portrait-note">Real projects. Measurable findings.</div></div></div></section>
<div class="tools"><div class="container tools-inner"><p>Tools I use to build<br> useful analytics</p><div class="tool-list">{''.join('<span>'+x+'</span>' for x in ['SQL','Python','Power BI','Tableau','BigQuery','dbt','Snowflake'])}</div></div></div>
<section class="section expertise" id="expertise"><div class="container two-col"><div class="expertise-stack">{expert_cards}</div><div class="section-copy"><div class="eyebrow">MY EXPERTISE</div><h2>What I do.<br><span class="accent">And how it helps.</span></h2><p>From raw data to business-ready insights, I build practical analytics across the full workflow.</p><p>My work connects thoughtful data preparation, clear visual storytelling, and analytical tools that make complex information easier to use.</p><a class="text-link" href="#projects">See my work in action <span class="arrow">↗</span></a></div></div></section>
<section class="section process"><div class="container process-grid"><div><div class="eyebrow">THE WAY I WORK</div><h2>From messy data<br>to meaningful<br><span class="accent">insights.</span></h2><p>A clear business question. Reliable data.<br>A useful answer.</p></div><div class="process-steps">{''.join(f'<div class="step"><div class="step-number">0{i+1}</div><div><h3>{t}</h3><p>{d}</p></div></div>' for i,(t,d) in enumerate([('Prepare','Validate, clean, and organize the data. Build a foundation that can be trusted.'),('Analyze','Model relationships, define KPIs, and investigate the business question.'),('Communicate','Build dashboards and applications that make the findings useful.')]))}</div></div></section>
<section class="section" id="projects"><div class="container"><div class="section-head"><div><div class="eyebrow">SELECTED WORK</div><h2>Data. Questions. <span class="accent">Answers.</span></h2><p>Three end-to-end projects spanning ecommerce, fintech, and location strategy.</p></div>{ext(C['github'],'All repositories ↗')}</div><div class="project-grid">{''.join(card(p,i) for i,p in enumerate(PROJECTS))}</div></div></section>
<section class="section about" id="about"><div class="container"><div class="two-col"><div><div class="eyebrow">BEHIND THE ANALYSIS</div><h2>A little <span class="accent">about me.</span></h2><div class="about-intro"><img src="/assets/portrait.jpg" alt="" width="64" height="64" loading="lazy"><div><strong>Saurav Chander Sharma</strong><span>Data Analyst · Toronto, Ontario</span></div></div><p>I enjoy finding the story hidden inside data — understanding what happened and how that information can help someone decide what to do next.</p><p>With a background in Computer Science &amp; Engineering and Project Management, I bring technical knowledge and an understanding of business objectives to my work. Through an industry internship and hands-on projects, I've worked with SQL transformations, star-schema modeling, dashboards, and decision-support tools.</p>{resume('text-link','Get to know my background · Resume ↓')}</div><div class="experience"><div class="eyebrow">EXPERIENCE · FEBRUARY 2022</div><h3>Data Analytics Intern</h3><p class="company">Bharat Heavy Electricals Limited (BHEL)</p><ul><li>Cleaned and validated COVID-19 datasets using SQL, identifying missing, duplicate, and inconsistent records to improve data accuracy and reliability.</li><li>Wrote SQL queries to filter, transform, and organize data used by the Digital Transformation Group (DTG) for internal reporting and web-based applications.</li><li>Supported data preparation, validation, and maintenance for ongoing digital initiatives within DTG.</li></ul>{ext(C['certificate'],'View Internship Certificate ↗')}</div></div><div class="education-grid"><div class="education"><div class="eyebrow">2018–2022 · EDUCATION</div><h3>B.Tech., Computer Science &amp; Engineering</h3><p>Galgotias University · India</p></div><div class="education"><div class="eyebrow">2023–2025 · EDUCATION</div><h3>Postgraduate Certificate, Project Management</h3><p>Algoma University · Ontario, Canada</p></div></div></div></section>
<section class="section" id="skills"><div class="container"><div class="section-head"><div><div class="eyebrow">MY TOOLKIT</div><h2>The skills behind the work.</h2><p>From the first SQL query to the final dashboard.</p></div></div><div class="skills-grid">{''.join(f'<div class="skill-group"><h3>{k}</h3>{tags(v)}</div>' for k,v in C['skills'].items())}</div></div></section>
<section class="contact" id="contact"><div class="container contact-grid"><div><div class="eyebrow">LET'S CONNECT</div><h2>Let's turn data<br>into <span class="accent">decisions.</span></h2></div><div><p>Have a Data Analyst opportunity or a project worth discussing? I'd love to connect.</p><a class="email-link" href="mailto:{C['email']}">Email Me <span class="circle-arrow">↗</span></a><div class="contact-bottom">{ext(C['linkedin'],'View LinkedIn ↗')}{resume('text-link','Download Resume ↓')}</div></div></div></section></main>'''

schema = {'@context':'https://schema.org','@type':'ProfilePage','mainEntity':{'@type':'Person','name':C['name'],'jobTitle':'Data Analyst','url':ORIGIN,'image':ORIGIN+'/assets/portrait.jpg','sameAs':[C['linkedin'],C['github']],'address':{'@type':'PostalAddress','addressLocality':'Toronto','addressRegion':'Ontario','addressCountry':'CA'}}}
(DIST/'index.html').write_text(page('Saurav Chander Sharma | Data Analyst Portfolio','Explore data analytics projects using SQL, Python, Power BI, Tableau, BigQuery, dbt, and Streamlit.',home,schema=schema),encoding='utf-8')
for i,p in enumerate(PROJECTS):
    repo = C['github']+'/'+p['repo']
    demo = ext(p['demo'],'Try Live Simulator ↗','btn secondary') if p.get('demo') else ''
    gallery = ''.join(f'<figure><a href="/assets/{p["slug"]}-{n+1}.webp" target="_blank" rel="noopener noreferrer" aria-label="Open full-size {e(alt)}"><img src="/assets/{p["slug"]}-{n+1}.webp" alt="{e(alt)}" loading="lazy"></a><figcaption>{e(alt)} · Original project visual · Select to view full size</figcaption></figure>' for n,alt in enumerate(p['images']))
    nxt=PROJECTS[(i+1)%len(PROJECTS)]
    body=f'''<main id="main"><section class="case-hero"><div class="container"><a class="breadcrumb" href="/#projects">← All Projects</a><div class="eyebrow">{p['category']} · {p['date']}</div><h1>{p['title']}</h1><p class="lead">{p['summary']}</p>{tags(p['stack'])}<div class="actions">{ext(repo,'Explore GitHub Repository ↗','btn')}{demo}</div></div></section><div class="container"><div class="case-stats">{''.join('<div>'+s+'</div>' for s in p['scope'])}</div><div class="case-layout"><aside class="case-aside" aria-label="Case study sections"><a href="#question">01 / The question</a><a href="#approach">02 / The approach</a><a href="#findings">03 / The findings</a><a href="#visuals">04 / Project visuals</a><a href="#limitations">05 / Context &amp; limitations</a></aside><div class="case-content"><section id="question"><div class="eyebrow">THE BUSINESS QUESTION</div><h2>{p['question']}</h2></section><section id="approach"><h2>From source data to analysis</h2><ol>{''.join('<li>'+x+'</li>' for x in p['methodology'])}</ol></section><section id="findings"><h2>What the analysis revealed</h2><div class="finding">{''.join('<p>'+x+'</p>' for x in p['findings'])}</div></section><section id="visuals"><h2>A closer look at the work</h2><p>Original visuals from this project's repository. Open any image to inspect it at full size.</p><div class="case-gallery">{gallery}</div>{ext(repo,'View source, models, and documentation on GitHub ↗')}</section><section id="limitations"><h2>Context &amp; limitations</h2><p>{p['limitations']}</p><p>This is a portfolio project. The figures describe the analyzed data and model outputs; they are not claims of client impact.</p></section></div></div><div class="next-project"><a class="text-link" href="/#projects">← All Projects</a><a href="/projects/{nxt['slug']}/"><span>NEXT PROJECT</span><strong>{nxt['shortTitle']} ↗</strong></a></div></div></main>'''
    target=DIST/'projects'/p['slug'];target.mkdir(parents=True,exist_ok=True)
    structured={'@context':'https://schema.org','@type':'CreativeWork','name':p['title'],'description':p['summary'],'author':{'@type':'Person','name':C['name']},'url':ORIGIN+'/projects/'+p['slug']+'/','codeRepository':repo}
    (target/'index.html').write_text(page(p['title']+' | Saurav Sharma',p['summary'],body,'/projects/'+p['slug']+'/',structured),encoding='utf-8')
notfound=page('Page not found | Saurav Sharma','Return to Saurav Sharma’s data analytics portfolio.','<main id="main" class="not-found"><div class="eyebrow">404 · PAGE NOT FOUND</div><h1>This path has no data.</h1><p>Let’s get you back to the projects.</p><a class="btn" href="/">Back Home ↗</a></main>','/404')
(DIST/'404.html').write_text(notfound,encoding='utf-8')
(DIST/'404').mkdir(exist_ok=True)
(DIST/'404'/'index.html').write_text(notfound,encoding='utf-8')
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+x+'</loc></url>' for x in ['/']+['/projects/'+p['slug']+'/' for p in PROJECTS])+'</urlset>')
(DIST/'assets'/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#102347"/><text x="15" y="46" font-family="Arial,sans-serif" font-size="43" font-weight="bold" fill="white">S</text><circle cx="51" cy="47" r="5" fill="#f36a0a"/></svg>')
print('Built homepage, 3 case studies, 404, sitemap, and metadata.')
